// A durable later monitor evaluation supersedes only its older timer check.
// TryClaim/Authorize retain the existing HeadCondition CAS and cancellation receipt.
// Archive, notification, recovery actions and original failures are never superseded.
public static bool SupersededMonitorCheck(OutboxEntry e,StoredSnapshot? state) =>
    e.Kind==WorkKind.DomainEffect && e.CancelIfObsolete && !e.Critical &&
    e.Intent?.Kind==EffectKind.ScheduleRecoveryCheck && state is not null &&
    state.Head.ContinuousMonitoring && state.Head.Key.Scope=="monitor" &&
    e.AggregateKey==state.AggregateKey && e.Intent.IncidentId==state.Head.Id &&
    e.Intent.Epoch==state.Head.Epoch && e.Intent.PolicyVersion==state.Head.PolicyVersion &&
    e.DueAt<state.Head.LastEvaluatedAt;
